components.css:
.ds-sample{font-family:SUIT,-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo',sans-serif;color:var(--ink,#1b2940);font-size:16px;line-height:1.6}
.ds-sample button,.ds-sample a{-webkit-tap-highlight-color:transparent}
.ds-sample button{font:inherit;color:inherit;cursor:pointer}
.ds-sample button:focus-visible,.ds-sample a:focus-visible,.ds-sample summary:focus-visible,.ds-sample .ds-table-scroll:focus-visible{outline:2px solid var(--accent,#b82e3e);outline-offset:4px}
.ds-sample button:disabled{color:#a0a8b3;cursor:default}
.ds-sample svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}
.ds-sample .ds-date-strip{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:0 0 8px;overscroll-behavior-x:contain}
.ds-sample .ds-date-strip::-webkit-scrollbar{display:none}
.ds-sample .ds-date-tab{flex:1 0 72px;display:flex;flex-direction:column;justify-content:center;align-items:center;min-height:76px;padding:8px 12px;border:0;border-radius:var(--radius,8px);background:transparent;transition:color 160ms var(--ease,cubic-bezier(.22,1,.36,1)),background-color 160ms var(--ease,cubic-bezier(.22,1,.36,1))}
.ds-sample .ds-date-tab:hover{background:var(--surface,#f4f6f8)}
.ds-sample .ds-weekday{font-size:12px;color:var(--secondary,#536174)}
.ds-sample .ds-date-number{font-size:24px;line-height:1.4;font-weight:500}
.ds-sample .ds-date-mark{font-size:12px;color:var(--secondary,#536174)}
.ds-sample .ds-date-tab[aria-selected=true]{background:var(--accent,#b82e3e);color:white}
.ds-sample .ds-date-tab[aria-selected=true] .ds-weekday,.ds-sample .ds-date-tab[aria-selected=true] .ds-date-mark{color:white}
@media (max-width:767px){.ds-sample .ds-date-strip{gap:4px}}
@media (max-width:767px){.ds-sample .ds-date-tab{flex:0 0 60px;padding:8px 4px}}
@media(prefers-reduced-motion:reduce){.ds-sample *{scroll-behavior:auto!important;transition:none!important}}
.ds-sample .ds-date-tab{border-radius:12px}.ds-sample .ds-date-tab[aria-selected=true]{box-shadow:0 3px 8px #1b294014}

