.ds-sample .ds-timeline{border-top:1px solid var(--line,#e0e5eb)}
.ds-sample .ds-event{display:grid;grid-template-columns:96px minmax(0,1fr);gap:16px;padding:24px 0;border-bottom:1px solid var(--line,#e0e5eb)}
.ds-sample .ds-event-time{color:var(--ink,#1b2940);font-size:14px;font-weight:500;line-height:1.6;padding-top:2px;overflow-wrap:anywhere}
.ds-sample .ds-time-start,.ds-sample .ds-time-end{display:block;white-space:nowrap}
.ds-sample .ds-time-end{color:var(--secondary,#536174)}
.ds-sample .ds-event-card{min-width:0}
.ds-sample .ds-card-top{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 12px}
.ds-sample .ds-event h3{font-size:17px;line-height:1.6;font-weight:500;margin:0;overflow-wrap:anywhere}
.ds-sample .ds-badge{font-size:12px;color:var(--muted,#657184);white-space:nowrap}
.ds-sample .ds-badge.ds-check{color:var(--warning,#875327);background:var(--warning-wash,#fcf5ed);padding:0 6px;border-radius:4px}
.ds-sample .ds-badge.ds-rest{color:#405a7b}
.ds-sample .ds-event-details{font-size:14px;line-height:1.7;color:var(--secondary,#536174);margin-top:4px}
.ds-sample .ds-event-details p{margin:0}
.ds-sample .ds-map-link{display:inline-flex;align-items:center;gap:4px;min-height:44px;font-size:13px;color:var(--ink,#1b2940);text-decoration:none}
.ds-sample .ds-map-link:hover{text-decoration:underline}
.ds-sample .ds-map-link svg{width:16px;height:16px}
@media (max-width:767px){.ds-sample .ds-event{grid-template-columns:68px minmax(0,1fr);gap:12px;padding:20px 0}}
@media (max-width:767px){.ds-sample .ds-event-time{font-size:13px}}
@media (max-width:767px){.ds-sample .ds-event h3{font-size:16px}}
@media (max-width:359px){.ds-sample .ds-event{grid-template-columns:60px minmax(0,1fr)}}
@media print{.ds-sample .ds-event{break-inside:avoid}}
@media(prefers-reduced-motion:reduce){.ds-sample *{scroll-behavior:auto!important;transition:none!important}}

