.ds-sample{font-family:SUIT,-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo',sans-serif;color:var(--ink,#1b2940);font-size:16px;line-height:1.6}
.ds-sample button,.ds-sample a{-webkit-tap-highlight-color:transparent}
