.ds-sample .ds-table-scroll{overflow:auto;max-width:100%;max-height:72vh;border:1px solid var(--line,#e0e5eb);border-radius:var(--radius,8px);scrollbar-color:#b4bdc9 #f4f6f8}
.ds-sample .ds-table-scroll table{border-collapse:separate;border-spacing:0;width:max-content;min-width:100%;font-size:13px}
.ds-sample .ds-table-scroll caption{text-align:left;font-size:13px;padding:16px}
.ds-sample .ds-table-scroll th,.ds-sample .ds-table-scroll td{width:224px;min-width:224px;max-width:224px;vertical-align:top;padding:16px;border-right:1px solid var(--line,#e0e5eb);border-bottom:1px solid var(--line,#e0e5eb);white-space:pre-line}
.ds-sample .ds-table-scroll th{font-weight:500}
.ds-sample .ds-table-scroll td strong{font-weight:500}
.ds-sample .ds-table-scroll td div{margin-top:4px;color:var(--secondary,#536174)}
.ds-sample .ds-table-scroll td small{display:block;margin-top:8px;color:var(--secondary,#536174);font-size:12px}
.ds-sample .ds-table-scroll th:first-child{width:80px;min-width:80px;max-width:80px;position:sticky;left:0;background:#f4f6f8;z-index:2}
.ds-sample .ds-table-scroll thead th{position:sticky;top:0;z-index:3;background:var(--ink,#1b2940);color:white}
.ds-sample .ds-table-scroll thead th:first-child{z-index:4;background:var(--ink,#1b2940)}
.ds-sample .ds-table-scroll td[data-kind=rest]{background:#f0f4f8}
.ds-sample .ds-table-scroll td[data-kind=check]{background:var(--warning-wash,#fcf5ed)}
.ds-sample .ds-table-scroll td[data-kind=cruise]{background:#f6f4f9}
.ds-sample .ds-table-scroll td[data-kind=meal]{background:#fbf8f2}
